264		}
265	
266		// Test clean working tree
267		hasChanges, err := HasUncommittedChanges(context.Background())
268		if err != nil {
269			t.Fatalf("HasUncommittedChanges(context.Background()) error = %v", err)
270		}
271		if hasChanges {
272			t.Error("HasUncommittedChanges(context.Background()) = true, want false for clean tree")
273		}
274	
275		// Make unstaged change
276		if err := os.WriteFile(testFile, []byte("modified"), 0o644); err != nil {
277			t.Fatalf("Failed to write test file: %v", err)
278		}
279	
280		// Test with unstaged changes
281		hasChanges, err = HasUncommittedChanges(context.Background())
282		if err != nil {
283			t.Fatalf("HasUncommittedChanges(context.Background()) error = %v", err)
284		}
285		if !hasChanges {
286			t.Error("HasUncommittedChanges(context.Background()) = false, want true for modified file")
287		}
288	
289		// Stage the change
290		if _, err := w.Add("test.txt"); err != nil {
291			t.Fatalf("Failed to add test file: %v", err)
292		}
293	
294		// Test with staged changes
295		hasChanges, err = HasUncommittedChanges(context.Background())
296		if err != nil {
297			t.Fatalf("HasUncommittedChanges(context.Background()) error = %v", err)
298		}
299		if !hasChanges {
300			t.Error("HasUncommittedChanges(context.Background()) = false, want true for staged file")
301		}
302	
303		// Commit and add untracked file
304		if _, err := w.Commit("second commit", &git.CommitOptions{
305			Author: &object.Signature{
306				Name:  "Test",
307				Email: "test@example.com",
308			},
309		}); err != nil {
310			t.Fatalf("Failed to commit: %v", err)
311		}
