313			t.Fatalf("Failed to write untracked file: %v", err)
314		}
315	
316		// Test with untracked file (should be true)
317		hasChanges, err = HasUncommittedChanges(context.Background())
318		if err != nil {
319			t.Fatalf("HasUncommittedChanges(context.Background()) error = %v", err)
320		}
321		if !hasChanges {
322			t.Error("HasUncommittedChanges(context.Background()) = false, want true for untracked file")
323		}
324	
325		// Clean up untracked file for next test
326		if err := os.Remove(filepath.Join(tmpDir, "untracked.txt")); err != nil {
327			t.Fatalf("Failed to remove untracked file: %v", err)
328		}
329	
330		// Test global gitignore (core.excludesfile) handling
331		// go-git doesn't read global gitignore, so we use git CLI instead.
332		// Simulate global gitignore by setting core.excludesfile in repo config.
333		// The file must be outside the repo to avoid showing up as untracked itself.
334		globalIgnoreDir := t.TempDir()
335		globalIgnoreFile := filepath.Join(globalIgnoreDir, "global-gitignore")
336		if err := os.WriteFile(globalIgnoreFile, []byte("*.globally-ignored\n"), 0o644); err != nil {
337			t.Fatalf("Failed to write global gitignore: %v", err)
338		}
339	
340		// Set core.excludesfile in repo config
341		cmd := exec.CommandContext(context.Background(), "git", "config", "core.excludesfile", globalIgnoreFile)
342		cmd.Dir = tmpDir
343		if err := cmd.Run(); err != nil {
344			t.Fatalf("Failed to set core.excludesfile: %v", err)
345		}
346	
347		// Create a file that matches the global ignore pattern
348		if err := os.WriteFile(filepath.Join(tmpDir, "secret.globally-ignored"), []byte("ignored"), 0o644); err != nil {
349			t.Fatalf("Failed to write globally ignored file: %v", err)
350		}
351	
352		// Test with globally gitignored file - should return false (clean)
353		// This catches regressions if someone switches back to go-git's Status()
354		// which doesn't read core.excludesfile (global gitignore)
355		hasChanges, err = HasUncommittedChanges(context.Background())
356		if err != nil {
357			t.Fatalf("HasUncommittedChanges(context.Background()) error = %v", err)
358		}
359		if hasChanges {
360			t.Error("HasUncommittedChanges(context.Background()) = true, want false for globally gitignored file (core.excludesfile)")
361		}
362	}
