364	func TestFindNewUntrackedFiles(t *testing.T) {
365		tests := []struct {
366			name        string
367			current     []string
368			preExisting []string
369			expected    []string
370		}{
371			{
372				name:        "finds new files not in pre-existing list",
373				current:     []string{"file1.go", "file2.go", "file3.go"},
374				preExisting: []string{"file1.go"},
375				expected:    []string{"file2.go", "file3.go"},
376			},
377			{
378				name:        "returns empty when all files pre-exist",
379				current:     []string{"file1.go", "file2.go"},
380				preExisting: []string{"file1.go", "file2.go"},
381				expected:    nil,
382			},
383			{
384				name:        "returns all files when pre-existing is empty",
385				current:     []string{"file1.go", "file2.go"},
386				preExisting: []string{},
387				expected:    []string{"file1.go", "file2.go"},
388			},
389			{
390				name:        "returns nil when current is empty",
391				current:     []string{},
392				preExisting: []string{"file1.go"},
393				expected:    nil,
394			},
395			{
396				name:        "handles nil current slice",
397				current:     nil,
398				preExisting: []string{"file1.go"},
399				expected:    nil,
400			},
401			{
402				name:        "handles nil pre-existing slice",
403				current:     []string{"file1.go", "file2.go"},
404				preExisting: nil,
405				expected:    []string{"file1.go", "file2.go"},
406			},
407			{
408				name:        "handles both nil slices",
409				current:     nil,
410				preExisting: nil,
411				expected:    nil,
412			},
413			{
414				name:        "handles files with paths",
415				current:     []string{"src/main.go", "src/utils.go", "test/main_test.go"},
416				preExisting: []string{"src/main.go"},
417				expected:    []string{"src/utils.go", "test/main_test.go"},
418			},
419			{
420				name:        "handles duplicate files in pre-existing",
421				current:     []string{"file1.go", "file2.go"},
422				preExisting: []string{"file1.go", "file1.go"},
423				expected:    []string{"file2.go"},
424			},
425			{
426				name:        "is case-sensitive",
427				current:     []string{"File.go", "file.go"},
428				preExisting: []string{"file.go"},
429				expected:    []string{"File.go"},
430			},
431		}
432	
433		for _, tt := range tests {
434			t.Run(tt.name, func(t *testing.T) {
435				result := findNewUntrackedFiles(tt.current, tt.preExisting)
436	
437				if len(result) != len(tt.expected) {
438					t.Errorf("findNewUntrackedFiles() returned %d files, want %d", len(result), len(tt.expected))
439					t.Errorf("got: %v, want: %v", result, tt.expected)
440					return
441				}
442	
443				// Create a map for easy lookup
444				expectedMap := make(map[string]bool)
445				for _, f := range tt.expected {
446					expectedMap[f] = true
447				}
448	
449				for _, f := range result {
450					if !expectedMap[f] {
451						t.Errorf("findNewUntrackedFiles() returned unexpected file %q", f)
452					}
453				}
454			})
455		}
456	}
