542	// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
543	// Uses "git fetch origin <hash>" which goes through normal credential helpers,
544	// unlike fetch-pack which bypasses them. Requires the server to support
545	// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
546	//
547	// If fetching by hash fails, falls back to a full metadata branch fetch.
548	func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
549		if len(hashes) == 0 {
550			return nil
551		}
552	
553		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
554		defer cancel()
555	
556		// Build fetch args: "git fetch --no-tags origin <hash1> <hash2> ..."
557		// This uses the normal transport + credential helpers, unlike fetch-pack.
558		args := []string{"fetch", "--no-tags", "--no-write-fetch-head", "origin"}
559		for _, h := range hashes {
560			args = append(args, h.String())
561		}
562	
563		fetchCmd := strategy.CheckpointGitCommand(ctx, "origin", args...)
564		if _, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
565			logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
566				slog.Int("blob_count", len(hashes)),
567				slog.String("error", fetchErr.Error()),
568			)
569			// Fallback: full metadata branch fetch (pack negotiation skips already-local objects)
570			if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
